<?php declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/otp_service.php';require __DIR__.'/inc/security.php';require_post_csrf();$id=(int)($_SESSION['otp_challenge_id']??0);$q=$pdo->prepare('SELECT * FROM otp_challenges WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)redirect('register.php');try{$new=issue_otp($pdo,$old['user_id'],$old['purpose'],$old['destination'],$old['email_key']);$_SESSION['otp_challenge_id']=$new['challenge_id'];$feedback=otp_delivery_feedback($new);$_SESSION['otp_notice']=$feedback['message'];$_SESSION['otp_notice_type']=$feedback['type'];}catch(Throwable $e){$_SESSION['otp_notice']=$e->getMessage();$_SESSION['otp_notice_type']='danger';}redirect('verify_otp.php');
